INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (1, 'Aperturas con mancuernas', 1, 'Túmbate en un banco plano con una mancuerna en cada mano, los brazos extendidos sobre el pecho, las palmas mirándose y los codos un poco flexionados. Abre los brazos hacia los lados hasta que las mancuernas lleguen a la altura del pecho y vuelve a juntarlas, sin cambiar el ángulo de los codos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (2, 'Cruce de poleas', 1, 'De pie entre dos poleas altas, con un pie adelantado y el tronco algo inclinado. Lleva los agarres hacia abajo y hacia el centro en arco hasta juntarlos delante de la cadera, con los codos un poco flexionados, y vuelve controlando el peso.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (3, 'Flexiones', 1, 'Apoya las manos algo más abiertas que los hombros y mantén el cuerpo recto de la cabeza a los talones. Baja hasta casi tocar el suelo con el pecho, con los codos a unos 45 grados del cuerpo, y empuja sin dejar que la cadera se hunda.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (4, 'Pec deck', 1, 'Siéntate con la espalda pegada al respaldo y los agarres a la altura del pecho. Junta los brazos delante apretando el pecho, con los codos un poco flexionados y fijos, y vuelve despacio hasta notar el estiramiento sin que los hombros se vayan hacia delante.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (5, 'Press banca con barra', 1, 'Túmbate con los ojos bajo la barra, los pies firmes en el suelo y los omóplatos juntos, y agárrala algo más abierta que los hombros. Bájala controlada hasta rozar la parte baja del pecho y empújala hasta estirar los brazos sin despegar la espalda alta del banco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (6, 'Press banca con mancuernas', 1, 'Túmbate en un banco plano con las mancuernas a los lados del pecho, los pies firmes en el suelo y los omóplatos juntos. Empújalas hacia arriba hasta casi tocarse y bájalas despacio hasta notar el estiramiento del pecho.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (7, 'Press banca en máquina', 1, 'Ajusta el asiento para que los agarres queden a la altura de la mitad del pecho. Con la espalda pegada al respaldo y los omóplatos juntos, empuja hasta casi estirar los brazos y vuelve despacio hasta notar el estiramiento del pecho.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (8, 'Press banca en multipower', 1, 'Coloca un banco plano centrado bajo la barra guiada, de forma que baje a la parte baja del pecho. Desengancha la barra girando las muñecas, bájala controlada y empújala hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (9, 'Press declinado con barra', 1, 'Túmbate en el banco declinado con las piernas bien sujetas y los omóplatos juntos, y agarra la barra algo más abierta que los hombros. Bájala controlada hasta la parte baja del pecho y empújala hasta estirar los brazos sin despegar la espalda del banco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (10, 'Press declinado con mancuernas', 1, 'Túmbate en el banco declinado con las piernas sujetas y las mancuernas a los lados de la parte baja del pecho. Empújalas hacia arriba hasta casi juntarlas y bájalas despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (11, 'Press inclinado con barra', 1, 'En un banco inclinado a unos 30-45 grados, con los pies firmes y los omóplatos juntos. Baja la barra hasta la parte alta del pecho, justo bajo las clavículas, y empújala hasta estirar los brazos sin despegar la espalda del respaldo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (12, 'Press inclinado con mancuernas', 1, 'En un banco inclinado a unos 30-45 grados, con las mancuernas a la altura de la parte alta del pecho. Empújalas hacia arriba hasta casi juntarlas y bájalas despacio hasta notar el estiramiento, sin despegar los omóplatos del respaldo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (13, 'Press inclinado en máquina', 1, 'Ajusta el asiento para que los agarres queden a la altura de la parte alta del pecho. Con la espalda pegada al respaldo, empuja hacia arriba y adelante hasta casi estirar los brazos y vuelve despacio, sin que los hombros se adelanten.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (14, 'Press inclinado en multipower', 1, 'Coloca un banco inclinado a unos 30-45 grados bajo la barra guiada, de forma que baje a la parte alta del pecho. Desengancha la barra, bájala controlada y empújala hasta casi estirar los brazos, sin despegar la espalda del respaldo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (15, 'Dominadas pronas', 2, 'Cuélgate de la barra con las palmas hacia delante, algo más abiertas que los hombros. Tira llevando los codos hacia abajo hasta pasar la barbilla por encima de la barra y baja hasta estirar los brazos del todo, sin balancearte ni dar impulso con las piernas.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (16, 'Dominadas supinas', 2, 'Cuélgate de la barra con las palmas mirando hacia ti, a la anchura de los hombros. Sube hasta pasar la barbilla por encima de la barra, llevando los codos hacia las costillas, y baja controlando hasta estirar los brazos, sin balancearte.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (17, 'Jalón en máquina', 2, 'Siéntate con los muslos sujetos bajo el rodillo y agarra las asas. Tira hacia abajo llevando los codos hacia los costados, con el pecho alto, hasta que las manos queden a la altura de los hombros. Sube despacio hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (18, 'Jalón en polea con agarre abierto', 2, 'Siéntate con los muslos sujetos y agarra la barra larga más abierta que los hombros. Tira hasta la parte alta del pecho llevando los codos hacia abajo, con el tronco apenas inclinado hacia atrás, y sube controlando hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (19, 'Jalón en polea con agarre cerrado', 2, 'Siéntate con los muslos sujetos y agarra el asa o la barra con las manos más juntas que los hombros. Tira hasta la parte baja del pecho pegando los codos al cuerpo y sacando el pecho, y sube despacio hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (20, 'Muscle-up', 2, 'Cuélgate de la barra y tira con fuerza y de forma explosiva hasta llevarla a la altura del pecho. Gira las muñecas por encima de ella pasando el pecho sobre la barra y termina empujando hasta estirar los brazos. Baja controlando hasta volver a colgarte.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (21, 'Pullover con mancuerna', 2, 'Túmbate en un banco plano con una mancuerna sujeta con las dos manos sobre el pecho. Llévala en arco por detrás de la cabeza con los codos un poco flexionados hasta notar el estiramiento y vuelve por el mismo camino.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (22, 'Pullover en polea', 2, 'De pie frente a una polea alta, con una barra o cuerda y el tronco algo inclinado. Con los brazos casi estirados, baja el agarre en arco hasta los muslos apretando la espalda y vuelve despacio sin doblar más los codos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (23, 'Remo con barra', 2, 'Inclina el tronco hacia delante con la espalda recta y las rodillas un poco flexionadas, con la barra colgando a la altura de las rodillas. Tira hacia el ombligo llevando los codos atrás y junta los omóplatos arriba. Baja controlando sin incorporarte.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (24, 'Remo con mancuerna', 2, 'Apoya una rodilla y la mano del mismo lado en un banco, con la espalda recta y la mancuerna en la otra mano. Tira de ella hacia la cadera llevando el codo atrás y pegado al cuerpo, y bájala hasta estirar el brazo sin girar el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (25, 'Remo con mancuernas en banco inclinado', 2, 'Túmbate boca abajo en un banco inclinado, con una mancuerna en cada mano y los brazos colgando. Tira llevando los codos hacia atrás hasta juntar los omóplatos y baja despacio hasta estirar los brazos, sin despegar el pecho del banco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (26, 'Remo en máquina', 2, 'Siéntate con el pecho contra el apoyo y agarra las asas con los brazos estirados. Tira llevando los codos hacia atrás hasta juntar los omóplatos y vuelve despacio hasta estirar los brazos, sin separar el pecho del apoyo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (27, 'Remo en máquina unilateral', 2, 'Siéntate con el pecho contra el apoyo y agarra un asa con un brazo estirado. Tira llevando el codo hacia atrás, pegado al cuerpo, hasta que la mano llegue al costado, y vuelve despacio hasta estirar el brazo, sin girar el tronco. Haz luego el otro brazo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (28, 'Remo en polea baja con agarre abierto', 2, 'Siéntate con los pies apoyados y las rodillas un poco flexionadas, y agarra la barra larga más abierta que los hombros, con los brazos estirados. Tira hacia la parte alta del abdomen llevando los codos atrás y abiertos, juntando los omóplatos, y vuelve despacio sin balancear el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (29, 'Remo en polea baja con agarre cerrado', 2, 'Siéntate con los pies apoyados y las rodillas un poco flexionadas, y agarra el asa estrecha con las palmas mirándose y los brazos estirados. Tira hacia el abdomen llevando los codos atrás, pegados al cuerpo, y juntando los omóplatos, con la espalda recta, y vuelve despacio sin balancear el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (30, 'Remo en polea baja unilateral', 2, 'Sentado frente a la polea baja con un asa de una mano, tira hacia la cadera llevando el codo atrás y vuelve hasta estirar el brazo. Mantén el tronco quieto y de frente, sin girarlo para ayudarte.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (31, 'Remo en T con agarre diagonal', 2, 'Coge las asas diagonales con las palmas mirando hacia dentro y los brazos estirados. Con la espalda recta, tira hacia el pecho llevando los codos atrás, pegados al cuerpo, y baja despacio hasta estirar los brazos, sin redondear la espalda.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (32, 'Remo en T con agarre horizontal', 2, 'Coge las asas anchas horizontales con las palmas hacia abajo y los brazos estirados. Con la espalda recta, tira hacia el pecho llevando los codos atrás y abiertos, y baja despacio hasta estirar los brazos, sin redondear la espalda.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (33, 'Remo invertido', 2, 'Túmbate bajo una barra fija a la altura de la cadera y agárrala con los brazos estirados, el cuerpo recto y los talones en el suelo. Tira hasta llevar el pecho a la barra juntando los omóplatos y baja despacio, sin que la cadera se hunda.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (34, 'Elevaciones frontales con mancuernas', 3, 'De pie, con una mancuerna en cada mano delante de los muslos. Sube los brazos hacia delante, casi estirados, hasta la altura de los hombros y bájalos despacio, sin balancear el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (35, 'Elevaciones frontales en polea', 3, 'De espaldas a una polea baja, con el cable entre las piernas y el agarre delante de los muslos. Sube el brazo o la barra hacia delante, casi estirado, hasta la altura de los hombros y baja despacio, sin balancear el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (36, 'Elevaciones laterales con mancuernas', 3, 'De pie, con una mancuerna en cada mano a los lados y los codos un poco flexionados. Sube los brazos hacia los lados hasta la altura de los hombros, guiando con los codos, y bájalos despacio, sin encoger los hombros ni balancearte.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (37, 'Elevaciones laterales en máquina', 3, 'Colócate en la máquina, sentado o de pie según el modelo, con los brazos o las manos en los apoyos y los hombros alineados con el eje de giro. Sube los brazos hacia los lados hasta la altura de los hombros y bájalos despacio, sin encogerlos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (38, 'Elevaciones laterales en polea', 3, 'De lado a una polea baja, agarra el asa con la mano más alejada. Sube el brazo hacia el lado hasta la altura del hombro, con el codo un poco flexionado, y baja despacio sin inclinar el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (39, 'Face pull', 3, 'Con una cuerda en la polea a la altura de la cara, tira hacia la frente separando las manos y llevando los codos altos y hacia atrás. Aguanta un momento con los omóplatos juntos y vuelve despacio hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (40, 'Flexiones en pica', 3, 'Apoya manos y pies en el suelo y sube la cadera hasta formar una V invertida. Dobla los codos bajando la cabeza hacia el suelo entre las manos y empuja hasta estirar los brazos, sin bajar la cadera.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (41, 'Pájaros con mancuernas', 3, 'Inclina el tronco hacia delante con la espalda recta y una mancuerna en cada mano colgando. Abre los brazos hacia los lados con los codos un poco flexionados hasta la altura de los hombros y baja despacio, sin incorporarte.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (42, 'Pájaros en polea', 3, 'Entre dos poleas a la altura de los hombros, cruza los cables y agarra cada uno con la mano contraria. Abre los brazos hacia atrás hasta quedar en cruz, con los codos un poco flexionados, y vuelve despacio sin mover el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (43, 'Pec deck inverso', 3, 'Siéntate mirando al respaldo de la máquina, con el pecho apoyado y los agarres delante a la altura de los hombros. Abre los brazos hacia atrás con los codos un poco flexionados hasta quedar en cruz y vuelve despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (44, 'Press Arnold', 3, 'Sentado, empieza con las mancuernas delante de la cara y las palmas mirándote. Empújalas hacia arriba girando las muñecas para que acaben mirando hacia delante, y baja deshaciendo el giro hasta la posición de partida.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (45, 'Press militar con barra', 3, 'De pie, con la barra apoyada sobre la parte alta del pecho y las manos algo más abiertas que los hombros. Aprieta abdomen y glúteos y empuja la barra en línea recta sobre la cabeza, apartando la cara al subir, y bájala controlada sin arquear la espalda.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (46, 'Press militar con mancuernas', 3, 'Sentado con respaldo, o de pie, con las mancuernas a la altura de los hombros y los codos un poco por delante del cuerpo. Empújalas hacia arriba hasta casi juntarlas y baja despacio hasta la altura de las orejas, sin arquear la espalda.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (47, 'Press militar en máquina', 3, 'Ajusta el asiento para que los agarres queden a la altura de los hombros. Con la espalda pegada al respaldo, empuja hacia arriba hasta casi estirar los brazos y baja despacio hasta la altura de los hombros, sin arquear la espalda.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (48, 'Remo al mentón', 3, 'De pie, con una barra o mancuernas delante de los muslos y las manos a la anchura de los hombros. Tira hacia arriba llevando los codos por encima de las manos hasta la altura del pecho, no más alto, y baja despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (49, 'Curl con barra', 4, 'De pie, con la barra agarrada por debajo a la anchura de los hombros y los codos pegados al cuerpo. Sube la barra doblando los codos sin moverlos hacia delante y bájala despacio hasta estirar los brazos, sin balancear el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (50, 'Curl con barra Z', 4, 'De pie, con la barra Z agarrada por debajo, las manos en sus tramos inclinados y los codos pegados al cuerpo. Sube la barra doblando los codos sin moverlos hacia delante y bájala despacio hasta estirar los brazos, sin balancear el tronco.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (51, 'Curl con mancuernas', 4, 'De pie o sentado, con una mancuerna en cada mano y las palmas hacia delante. Sube doblando los codos, a la vez o un brazo cada vez, sin separarlos del cuerpo, y baja despacio hasta estirar el brazo del todo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (52, 'Curl concentrado', 4, 'Sentado, apoya la parte de atrás del brazo en el interior del muslo con la mancuerna colgando. Sube la mancuerna hacia el hombro doblando el codo, sin mover el brazo, y baja despacio hasta estirarlo del todo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (53, 'Curl en máquina', 4, 'Ajusta el asiento para que los codos queden apoyados y alineados con el eje de la máquina. Sube doblando los codos hasta arriba y baja despacio hasta casi estirar los brazos, sin despegar los brazos del apoyo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (54, 'Curl en polea', 4, 'De pie frente a una polea baja, con una barra y los codos pegados al cuerpo. Sube doblando los codos sin moverlos hacia delante y baja despacio hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (55, 'Curl inclinado con mancuernas', 4, 'Sentado en un banco inclinado hacia atrás, con una mancuerna en cada mano y los brazos colgando por detrás del cuerpo. Sube las mancuernas doblando los codos sin adelantarlos y baja hasta estirar los brazos del todo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (56, 'Curl martillo con mancuernas', 4, 'De pie, con una mancuerna en cada mano y las palmas mirándose. Sube doblando los codos sin girar las muñecas y sin separar los codos del cuerpo, y baja despacio hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (57, 'Curl martillo en polea', 4, 'De pie frente a una polea baja, con una cuerda agarrada por sus extremos, las palmas mirándose y los codos pegados al cuerpo. Sube doblando los codos sin girar las muñecas y baja despacio hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (58, 'Curl predicador', 4, 'Siéntate con la parte de atrás de los brazos apoyada en el banco inclinado y la barra o las mancuernas en las manos. Sube doblando los codos y baja despacio casi hasta estirarlos del todo, sin despegar los brazos del apoyo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (59, 'Extensión de tríceps en máquina', 5, 'Siéntate con los codos apoyados y alineados con el eje de la máquina. Empuja estirando los brazos del todo y vuelve despacio hasta que los codos queden doblados, sin despegarlos del apoyo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (60, 'Extensión de tríceps en polea', 5, 'De pie frente a una polea alta, con una barra o cuerda y los codos pegados a los costados. Estira los brazos hacia abajo hasta bloquear los codos y vuelve despacio hasta que los antebrazos queden paralelos al suelo, sin mover los codos de su sitio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (61, 'Extensión de tríceps sobre la cabeza', 5, 'Con una mancuerna sujeta con las dos manos, o una cuerda en la polea, lleva los brazos por encima de la cabeza. Baja el peso por detrás de la cabeza doblando los codos, que apuntan hacia arriba, y estíralos de nuevo sin abrirlos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (62, 'Flexiones diamante', 5, 'Apoya las manos juntas bajo el pecho, tocándose los pulgares y los índices, con el cuerpo recto de la cabeza a los talones. Baja con los codos pegados al cuerpo hasta casi tocar las manos con el pecho y empuja hasta estirar los brazos.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (63, 'Fondos en banco', 5, 'Sentado en el borde de un banco, apoya las manos a los lados de la cadera y adelanta los pies. Baja doblando los codos hacia atrás hasta que queden casi en ángulo recto y sube estirándolos, con la espalda cerca del banco.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (64, 'Fondos en máquina', 5, 'Siéntate con los agarres a los lados y la espalda contra el respaldo. Empuja hacia abajo hasta estirar los brazos y sube despacio hasta que los codos queden doblados, sin dejar que los hombros se vayan hacia delante.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (65, 'Fondos en paralelas', 5, 'Sujétate en las paralelas con los brazos estirados. Baja doblando los codos hasta que los hombros queden a la altura de los codos y sube hasta estirarlos, sin balancear las piernas.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (66, 'Patada de tríceps', 5, 'Con una mancuerna en una mano, apoya la otra mano y la rodilla del mismo lado en un banco, con la espalda recta. Pega el codo al costado con el brazo paralelo al suelo y estira el codo hacia atrás hasta tener el brazo recto. Vuelve despacio moviendo solo el antebrazo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (67, 'Press banca con agarre cerrado', 5, 'Túmbate en un banco plano con la barra agarrada a la anchura de los hombros, los pies firmes y los omóplatos juntos. Baja la barra hasta la parte baja del pecho con los codos pegados al cuerpo y empújala hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (68, 'Press francés', 5, 'Tumbado en un banco, con una barra Z o mancuernas sobre el pecho y los brazos estirados. Baja el peso hacia la frente doblando solo los codos, que apuntan al techo, y estíralos de nuevo sin abrirlos ni moverlos hacia atrás.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (69, 'Colgarse de la barra', 6, 'Cuélgate de una barra con los brazos estirados y las manos a la anchura de los hombros. Aguanta el tiempo que te marques con los hombros bajados, lejos de las orejas, y sin balancearte.', 1, 'tiempo', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (70, 'Curl de muñeca', 6, 'Sentado, con una barra o una mancuerna en las manos, apoya los antebrazos en los muslos o en un banco con las palmas hacia arriba y las muñecas por fuera. Baja el peso doblando la muñeca y súbelo todo lo que puedas, moviendo solo la muñeca.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (71, 'Curl inverso', 6, 'De pie, con una barra agarrada por encima, las palmas hacia abajo. Sube doblando los codos sin separarlos del cuerpo ni girar las muñecas, y baja despacio hasta estirar los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (72, 'Extensión de muñeca', 6, 'Sentado, con una barra o una mancuerna en las manos, apoya los antebrazos en los muslos o en un banco con las palmas hacia abajo y las muñecas por fuera. Sube el dorso de la mano todo lo que puedas y baja despacio, moviendo solo la muñeca.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (73, 'Paseo del granjero', 6, 'Coge una mancuerna o pesa rusa en cada mano y camina con pasos cortos, el tronco erguido y los hombros atrás. Aguanta el tiempo que te marques sin dejar que el peso te incline hacia un lado.', 1, 'tiempo', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (74, 'Extensión de cuádriceps', 7, 'Siéntate con la espalda pegada al respaldo y el rodillo sobre los tobillos, con las rodillas alineadas con el eje de la máquina. Estira las piernas del todo, aguanta un instante arriba y baja despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (75, 'Prensa de piernas', 7, 'Siéntate con la espalda y la cadera pegadas al respaldo y los pies a la anchura de los hombros en la plataforma. Baja doblando las rodillas hasta que la cadera vaya a despegarse y empuja sin bloquear las rodillas del todo arriba.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (76, 'Sentadilla', 7, 'De pie y sin peso, con los pies algo más abiertos que la cadera y los brazos al frente. Baja como si te sentaras en una silla, con la espalda recta y los talones en el suelo, hasta que los muslos queden paralelos al suelo, y sube.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (77, 'Sentadilla búlgara', 7, 'De espaldas a un banco, apoya en él el empeine del pie de atrás y adelanta bien el otro pie. Baja doblando la rodilla de delante hasta que el muslo quede casi paralelo al suelo y sube empujando con ese pie, con el tronco erguido.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (78, 'Sentadilla con barra', 7, 'Con la barra apoyada en la parte alta de la espalda y los pies algo más abiertos que la cadera. Baja echando la cadera atrás y abajo, con el pecho alto y las rodillas siguiendo la línea de los pies, hasta que los muslos queden paralelos al suelo, y sube empujando el suelo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (79, 'Sentadilla con salto', 7, 'Baja en sentadilla con la espalda recta y, al subir, salta con fuerza estirando todo el cuerpo. Cae suave sobre la parte delantera de los pies, doblando las rodillas para amortiguar, y encadena la siguiente.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (80, 'Sentadilla en multipower', 7, 'Con la barra guiada sobre la parte alta de la espalda y los pies un poco adelantados respecto a ella. Baja con la espalda recta hasta que los muslos queden paralelos al suelo y sube empujando con todo el pie.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (81, 'Sentadilla frontal', 7, 'Con la barra apoyada delante de los hombros, sujeta con los dedos y los codos altos. Baja con el tronco muy erguido hasta que los muslos queden paralelos al suelo y sube manteniendo los codos arriba para que la barra no se vaya hacia delante.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (82, 'Sentadilla goblet', 7, 'Sujeta una mancuerna o pesa rusa pegada al pecho con las dos manos. Baja con el tronco erguido, abriendo las rodillas entre los codos, hasta abajo del todo, y sube empujando con todo el pie.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (83, 'Sentadilla hack', 7, 'En la máquina, con la espalda contra el respaldo, los hombros bajo las almohadillas y los pies en la plataforma. Baja doblando las rodillas todo lo que puedas sin despegar la espalda y sube empujando con todo el pie.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (84, 'Subidas al cajón', 7, 'Pon un pie entero encima de un cajón o banco. Sube empujando con esa pierna hasta quedar de pie encima, sin impulsarte con la de abajo, y baja despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (85, 'Zancadas', 7, 'De pie, da un paso largo hacia delante y baja hasta que las dos rodillas queden casi en ángulo recto, sin que la de atrás toque el suelo. Vuelve empujando con el pie de delante, con el tronco erguido.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (86, 'Curl femoral sentado', 8, 'Siéntate con el rodillo detrás de los tobillos y el de sujeción sobre los muslos. Dobla las rodillas llevando los talones hacia abajo y atrás todo lo que puedas y vuelve despacio hasta casi estirarlas.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (87, 'Curl femoral tumbado', 8, 'Túmbate boca abajo con el rodillo detrás de los tobillos y las rodillas justo fuera del banco. Lleva los talones hacia los glúteos sin despegar la cadera del banco y baja despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (88, 'Curl nórdico', 8, 'De rodillas, con los tobillos sujetos por un compañero o un apoyo. Déjate caer hacia delante con el cuerpo recto de las rodillas a la cabeza, frenando todo lo que puedas, y apóyate con las manos al final para volver.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (89, 'Peso muerto a una pierna', 8, 'De pie sobre una pierna, con una mancuerna en la mano del otro lado. Inclina el tronco hacia delante mientras la pierna libre sube estirada por detrás, con la espalda recta, hasta notar el estiramiento detrás del muslo, y vuelve.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (90, 'Peso muerto con barra', 8, 'De pie con los pies a la anchura de la cadera y la barra en el suelo, pegada a las espinillas. Agárrala por fuera de las piernas, baja la cadera y saca el pecho con la espalda recta. Levántala empujando el suelo con los pies y la barra pegada a las piernas, hasta quedar de pie, y bájala por el mismo camino.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (91, 'Peso muerto con barra hexagonal', 8, 'De pie dentro de la barra hexagonal, con los pies a la anchura de la cadera. Baja la cadera, agarra las asas con las palmas mirándose y saca el pecho con la espalda recta. Levántala empujando el suelo con los pies hasta quedar de pie y bájala por el mismo camino.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (92, 'Peso muerto con mancuernas', 8, 'De pie, con una mancuerna en cada mano delante de los muslos. Echa la cadera atrás y dobla las rodillas, con la espalda recta y las mancuernas pegadas a las piernas, hasta que lleguen a la mitad de las espinillas. Sube empujando el suelo con los pies y aprieta los glúteos arriba.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (93, 'Peso muerto rumano con barra', 8, 'De pie, con la barra delante de los muslos y las rodillas un poco flexionadas. Echa la cadera atrás bajando la barra pegada a las piernas hasta notar el estiramiento detrás del muslo, con la espalda recta, y vuelve apretando los glúteos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (94, 'Peso muerto rumano con mancuernas', 8, 'De pie, con una mancuerna en cada mano delante de los muslos y las rodillas un poco flexionadas. Echa la cadera atrás bajando las mancuernas pegadas a las piernas hasta notar el estiramiento detrás del muslo, con la espalda recta, y vuelve apretando los glúteos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (95, 'Hip thrust', 9, 'Siéntate en el suelo con la parte alta de la espalda apoyada en un banco, la barra sobre la cadera y los pies en el suelo con las rodillas dobladas. Sube la cadera hasta que el tronco quede recto desde los hombros a las rodillas, aprieta los glúteos arriba y baja despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (96, 'Hip thrust en máquina', 9, 'En la máquina, con la espalda contra el apoyo y el cinturón sobre la cadera. Sube la cadera hasta quedar recto desde los hombros a las rodillas, aprieta los glúteos un instante y baja despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (97, 'Patada de glúteo en máquina', 9, 'Apoya el pecho o los brazos en la máquina y la planta del pie en la plataforma. Empuja la pierna hacia atrás y arriba apretando el glúteo, sin arquear la zona lumbar, y vuelve despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (98, 'Patada de glúteo en polea', 9, 'Con la tobillera enganchada a una polea baja y las manos apoyadas delante. Lleva la pierna hacia atrás, casi estirada, apretando el glúteo, sin arquear la espalda, y vuelve despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (99, 'Peso muerto sumo', 9, 'Con los pies muy abiertos, las puntas hacia fuera y la barra en el suelo pegada a las espinillas, agárrala por dentro de las piernas. Baja la cadera con el pecho alto y sube empujando el suelo hacia los lados y apretando los glúteos, con la barra pegada al cuerpo.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (100, 'Puente de glúteo', 9, 'Tumbado boca arriba con las rodillas dobladas y los pies apoyados cerca de los glúteos. Sube la cadera hasta quedar recto desde los hombros a las rodillas, aprieta los glúteos arriba y baja despacio.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (101, 'Elevación de talones de pie', 10, 'De pie, con la punta de los pies en un escalón y los talones por fuera. Baja los talones todo lo que puedas y sube hasta quedar de puntillas, con las rodillas casi estiradas, aguantando un instante arriba.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (102, 'Elevación de talones en prensa', 10, 'En la prensa de piernas, con solo la punta de los pies en el borde bajo de la plataforma y las rodillas casi estiradas. Empuja con las puntas hasta estirar los tobillos del todo y vuelve despacio hasta notar el estiramiento.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (103, 'Elevación de talones sentado', 10, 'Sentado en la máquina, con las almohadillas sobre los muslos y la punta de los pies en el apoyo. Baja los talones hasta notar el estiramiento y sube todo lo que puedas, aguantando un instante arriba.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (104, 'Abdominales en V', 11, 'Tumbado boca arriba con brazos y piernas estirados. Sube a la vez el tronco y las piernas hasta intentar tocar los pies con las manos, formando una V, y baja despacio sin llegar a apoyarte del todo.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (105, 'Crunch abdominal', 11, 'Tumbado boca arriba con las rodillas dobladas y las manos junto a la cabeza. Despega los hombros del suelo llevando el pecho hacia las rodillas, con la zona lumbar apoyada, y baja despacio. No tires del cuello con las manos.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (106, 'Crunch bicicleta', 11, 'Tumbado boca arriba, con las manos junto a la cabeza y las piernas en el aire. Lleva un codo hacia la rodilla contraria mientras estiras la otra pierna y alterna los lados con calma, sin tirar del cuello.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (107, 'Crunch en máquina', 11, 'Siéntate con los pies sujetos y los agarres o almohadillas a la altura del pecho. Dobla el tronco hacia delante llevando el pecho hacia las rodillas y vuelve despacio, sin empujar con los brazos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (108, 'Crunch en polea', 11, 'De rodillas frente a una polea alta, con la cuerda junto a la cabeza. Dobla el tronco hacia abajo llevando los codos hacia los muslos, sin bajar la cadera, y vuelve despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (109, 'Crunch inverso', 11, 'Tumbado boca arriba con las piernas dobladas en el aire y los brazos en el suelo. Despega la cadera del suelo llevando las rodillas hacia el pecho y baja despacio, sin impulso.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (110, 'Elevación de piernas colgado', 11, 'Colgado de una barra, con el cuerpo quieto. Sube las piernas, estiradas o dobladas, hasta al menos la altura de la cadera, curvando la pelvis hacia arriba, y bájalas despacio sin balancearte.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (111, 'Elevación de piernas tumbado', 11, 'Tumbado boca arriba con las piernas estiradas y las manos bajo la cadera. Sube las piernas hasta la vertical y bájalas despacio sin llegar a tocar el suelo, sin que la zona lumbar se despegue.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (112, 'Elevación de rodillas en paralelas', 11, 'Sujétate en las paralelas con los brazos estirados y el cuerpo quieto. Sube las rodillas hacia el pecho y bájalas despacio, sin balancear las piernas.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (113, 'Hollow hold', 11, 'Tumbado boca arriba, pega la zona lumbar al suelo y despega a la vez los hombros y las piernas estiradas, con los brazos por encima de la cabeza. Aguanta el cuerpo en forma de barca sin que la zona lumbar se levante.', 1, 'tiempo', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (114, 'Plancha', 11, 'Apoya los antebrazos, con los codos bajo los hombros, y las puntas de los pies. Mantén el cuerpo recto de la cabeza a los talones, apretando abdomen y glúteos, sin que la cadera se hunda ni suba.', 1, 'tiempo', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (115, 'Rueda abdominal', 11, 'De rodillas, con la rueda en el suelo delante. Rueda hacia delante estirando el cuerpo todo lo que puedas sin que la zona lumbar se hunda y vuelve tirando con el abdomen.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (116, 'Sit-ups', 11, 'Tumbado boca arriba con las rodillas dobladas y los pies sujetos o apoyados. Sube el tronco entero hasta quedar sentado y baja despacio hasta apoyar la espalda, sin dar tirones con los brazos.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (117, 'Encogimientos con barra', 12, 'De pie, con la barra delante de los muslos y los brazos estirados. Sube los hombros hacia las orejas, aguanta un instante arriba y baja despacio, sin girarlos ni doblar los codos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (118, 'Encogimientos con mancuernas', 12, 'De pie, con una mancuerna en cada mano a los lados y los brazos estirados. Sube los hombros hacia las orejas, aguanta un instante arriba y baja despacio, sin girarlos ni doblar los codos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (119, 'Encogimientos en máquina', 12, 'En la máquina, con los agarres a los lados y los brazos estirados. Sube los hombros hacia las orejas, aguanta un momento y baja despacio, sin doblar los codos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (120, 'Buenos días', 13, 'Con la barra apoyada en la parte alta de la espalda y las rodillas un poco flexionadas. Inclina el tronco hacia delante echando la cadera atrás, con la espalda recta, hasta notar el estiramiento detrás del muslo, y vuelve.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (121, 'Hiperextensiones', 13, 'En el banco de hiperextensiones, con la cadera en el borde del apoyo y los pies sujetos. Baja el tronco doblando la cadera y sube hasta quedar en línea con las piernas, sin pasarte arqueando la espalda.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (122, 'Flexión lateral con mancuerna', 14, 'De pie, con una mancuerna en una mano y la otra en la cintura. Inclina el tronco hacia el lado de la mancuerna y vuelve hasta quedar recto, sin girar el cuerpo ni echarlo hacia delante. Haz luego el otro lado.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (123, 'Leñador en polea', 14, 'De lado a una polea alta, agarra el asa con las dos manos. Llévala en diagonal hacia la rodilla contraria girando el tronco, con los brazos casi estirados, y vuelve despacio.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (124, 'Plancha lateral', 14, 'Túmbate de lado apoyado en un antebrazo, con el codo bajo el hombro y los pies uno sobre otro. Sube la cadera hasta que el cuerpo quede recto y aguanta sin dejarla caer.', 1, 'tiempo', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (125, 'Russian twist', 14, 'Sentado, con las rodillas dobladas, los pies en el suelo y el tronco inclinado hacia atrás con la espalda recta. Gira el tronco de un lado a otro llevando las manos juntas hasta el suelo junto a la cadera.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (126, 'Máquina de aductores', 15, 'Sentado, con las almohadillas por dentro de las rodillas y las piernas abiertas. Junta las piernas apretando la parte interior de los muslos y vuelve a abrirlas despacio, sin dejar que el peso choque.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (127, 'Máquina de abductores', 16, 'Sentado, con las almohadillas por fuera de las rodillas y las piernas juntas. Ábrelas apretando la parte de fuera de la cadera y vuelve a cerrarlas despacio, sin dejar que el peso choque.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (128, 'Flexión de cuello con disco', 17, 'Tumbado boca arriba en un banco, con la cabeza por fuera y un disco sobre la frente, sujeto con las manos y protegido con una toalla. Baja la cabeza despacio y súbela llevando la barbilla al pecho.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (129, 'Bicicleta al aire libre', 18, 'Ajusta el sillín para que la pierna quede casi estirada con el pedal abajo. Lleva casco, pedalea con la espalda recta y los brazos un poco doblados, a un ritmo que puedas sostener.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (130, 'Bicicleta de aire', 18, 'Siéntate con los pies en los pedales y las manos en los manillares móviles. Pedalea a la vez que empujas y tiras de los manillares con los brazos, con la espalda recta y a un ritmo que puedas sostener.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (131, 'Bicicleta estática', 18, 'Ajusta el sillín para que la rodilla quede apenas doblada con el pedal abajo y el manillar a una altura cómoda. Pedalea con la espalda recta y una resistencia que te deje mantener el ritmo.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (132, 'Caminar', 18, 'Camina a paso ligero, con la espalda erguida y la mirada al frente, apoyando primero el talón y moviendo los brazos al ritmo de los pasos.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (133, 'Cinta de correr', 18, 'Empieza caminando unos minutos y ve subiendo la velocidad. Corre cerca del centro de la cinta, con el tronco erguido y sin agarrarte a las barras.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (134, 'Comba', 18, 'Salta con la parte delantera de los pies, a poca altura, girando la cuerda con las muñecas y los codos cerca del cuerpo. Mantén el tronco erguido y aterriza suave, con las rodillas un poco flexionadas.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (135, 'Correr al aire libre', 18, 'Empieza a un ritmo suave para calentar y corre con zancadas cortas, los pies cayendo bajo el cuerpo, el tronco erguido y los brazos relajados.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (136, 'Elíptica', 18, 'Pedalea empujando con todo el pie, sin despegar los talones, y mueve los brazos con las barras. Mantén la espalda recta sin apoyar el peso en los brazos.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (137, 'Escaladora', 18, 'Sube los peldaños apoyando todo el pie, con el tronco erguido y las manos en las barras solo para equilibrarte, sin colgarte de ellas.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (138, 'Natación', 18, 'Nada al estilo que prefieras a un ritmo que puedas mantener, con el cuerpo estirado en el agua y respirando con regularidad.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (139, 'Remo ergómetro', 18, 'Siéntate con los pies sujetos en los apoyos y agarra el asa con los brazos estirados. Empuja primero con las piernas, luego echa el tronco un poco atrás y termina tirando del asa hacia el abdomen. Para volver, al revés: brazos, tronco y piernas.', 1, 'cardio', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (140, 'Arrancada', 19, 'Con la barra en el suelo y un agarre muy abierto, súbela de un solo movimiento explosivo desde el suelo hasta encima de la cabeza, metiéndote debajo en sentadilla con los brazos estirados, y levántate con ella arriba.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (141, 'Burpees', 19, 'De pie, baja a apoyar las manos en el suelo, lleva los pies atrás y haz una flexión. Recoge los pies junto a las manos y salta estirando el cuerpo con los brazos arriba.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (142, 'Cargada de potencia', 19, 'Con la barra en el suelo y las manos algo más abiertas que los hombros, súbela con un tirón explosivo de piernas y cadera y recíbela apoyada delante de los hombros, con los codos altos y las rodillas un poco dobladas.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (143, 'Cuerdas de batalla', 19, 'De pie, con las rodillas un poco dobladas y una cuerda en cada mano. Mueve los brazos arriba y abajo con fuerza, alternos o a la vez, para hacer ondas, aguantando el tiempo marcado sin perder la postura.', 1, 'tiempo', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (144, 'Dos tiempos', 19, 'Sube la barra del suelo a los hombros con un tirón explosivo y, desde ahí, llévala por encima de la cabeza con un empuje de piernas, metiéndote debajo con un pie adelante y otro atrás. Junta los pies con la barra arriba.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (145, 'Empuje de trineo', 19, 'Agarra las barras del trineo con los brazos casi estirados y el cuerpo inclinado. Empuja con pasos cortos y potentes, apoyando la parte delantera del pie, manteniendo la espalda recta durante el tiempo marcado.', 1, 'tiempo', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (146, 'Kettlebell swing', 19, 'Con la pesa rusa entre los pies, échala atrás entre las piernas doblando la cadera y lánzala hacia delante hasta la altura del pecho con un golpe de cadera, apretando los glúteos y con los brazos relajados.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (147, 'Levantamiento turco', 19, 'Tumbado con una pesa rusa en un brazo estirado hacia el techo, ponte de pie paso a paso sin bajar el brazo ni dejar de mirar la pesa, y vuelve a tumbarte deshaciendo los pasos.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (148, 'Mountain climbers', 19, 'En posición de flexión con los brazos estirados, lleva una rodilla hacia el pecho y cambia de pierna rápidamente, como si corrieras, sin subir la cadera. Mantén el ritmo el tiempo marcado.', 1, 'tiempo', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (149, 'Saltos al cajón', 19, 'De pie frente a un cajón estable, salta con los dos pies a la vez y cae suave encima, con las rodillas dobladas. Ponte de pie arriba y baja andando, no saltando hacia atrás.', 1, 'corporal', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (150, 'Thruster', 19, 'Con la barra o las mancuernas delante de los hombros, baja en sentadilla con el tronco erguido y, al subir, aprovecha el impulso para empujar el peso por encima de la cabeza en un solo movimiento.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (151, 'Wall ball', 19, 'Frente a una pared, con un balón medicinal sujeto delante del pecho. Baja en sentadilla y, al subir, lanza el balón a un punto alto de la pared. Recógelo y encadena la siguiente sentadilla.', 1, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (152, 'Press d''Alembert', 1, 'Con «comillas», tildes (áéíóúñ) y un apóstrofo: l''ejercici.', 0, 'peso_reps', NULL, '2026-09-01T10:00:00.000Z', '2026-09-01T10:00:00.000Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (153, 'Fondos lastrados', 5, NULL, 0, 'corporal', NULL, '2026-09-01T10:00:00.001Z', '2026-09-01T10:00:00.001Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (154, 'Plancha con toalla', 11, NULL, 0, 'tiempo', NULL, '2026-09-01T10:00:00.002Z', '2026-09-01T10:00:00.002Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (155, 'Bici del garaje', 18, NULL, 0, 'cardio', NULL, '2026-09-01T10:00:00.003Z', '2026-09-01T10:00:00.003Z');
INSERT INTO ejercicios (id, nombre, grupo_muscular_id, descripcion, es_predefinido, tipo_registro, oculto_desde, created_at, updated_at) VALUES (156, 'Curl en barra Z casero', 4, NULL, 0, 'peso_reps', '2026-09-17', '2026-09-01T10:00:00.004Z', '2026-11-12T17:52:09.553Z');
